selector_to_html = {"a[href=\"intro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Get Started<a class=\"headerlink\" href=\"#get-started\" title=\"Link to this heading\">#</a></h1><h2>1. Prepare your workspace.<a class=\"headerlink\" href=\"#prepare-your-workspace\" title=\"Link to this heading\">#</a></h2>", "a[href=\"git/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Version Control<a class=\"headerlink\" href=\"#version-control\" title=\"Link to this heading\">#</a></h1><p>Track changes to versioned project artifacts and supporting materials\nusing <a class=\"reference external\" href=\"https://git-scm.com/\">Git</a>, a free and open source distributed\nversion control system.</p>", "a[href=\"deploy/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Continuous Delivery<a class=\"headerlink\" href=\"#continuous-delivery\" title=\"Link to this heading\">#</a></h1>", "a[href=\"#structure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Structure<a class=\"headerlink\" href=\"#structure\" title=\"Link to this heading\">#</a></h2><p>This document contains three major sections.  The frontmatter\nintroduces the RDCT Engineering team\u2019s DevOps strategy and outlines\nthe <a class=\"reference external\" href=\"https://en.wikipedia.org/wiki/Happy_path#\">happy path</a> for new projects.  The main body of\nthe work provides instructions covering project management, version\ncontrol, continuous integration, and continuous delivery as well as\nsupplementary\u2014but still authoritative\u2014guidance for specific tool\nchains or techniques.  Appendices organize key reference materials.</p>", "a[href=\"#introduction\"]": "<h1 class=\"sd-d-none tippy-header\" style=\"margin-top: 0;\">Introduction<a class=\"headerlink\" href=\"#introduction\" title=\"Link to this heading\">#</a></h1><h2>Conventions<a class=\"headerlink\" href=\"#conventions\" title=\"Link to this heading\">#</a></h2><p>Authoritative guidance using these key words appear in admonitions\ntitled \u201cGuidance\u201d, like above.  An explanation of the rationale for\nthe rule plus supporting material appears after in separate\nparagraphs, like this.  Usually, each rule falls under its own\nsubheading, which facilitates cross-referencing.  Top-level headings\nprovide a content summary or a quick reference.</p>", "a[href=\"#conventions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Conventions<a class=\"headerlink\" href=\"#conventions\" title=\"Link to this heading\">#</a></h2><p>Authoritative guidance using these key words appear in admonitions\ntitled \u201cGuidance\u201d, like above.  An explanation of the rationale for\nthe rule plus supporting material appears after in separate\nparagraphs, like this.  Usually, each rule falls under its own\nsubheading, which facilitates cross-referencing.  Top-level headings\nprovide a content summary or a quick reference.</p>", "a[href=\"#audience\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Audience<a class=\"headerlink\" href=\"#audience\" title=\"Link to this heading\">#</a></h2><p>Members of the RDCT Engineering team follow these standards and\npractices as they develop and operate accredited, validated systems\nfor government, for research and education, and for commerce.  This is\nnot limited to pure software development activites and can include,\nfor example, documentation or system integrations.  This also includes\ncompany (internal) projects, which act as both on-the-job DevOps\ntraining activities and process quality controls.</p>", "a[href=\"build/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Continuous Integration<a class=\"headerlink\" href=\"#continuous-integration\" title=\"Link to this heading\">#</a></h1>", "a[href=\"training.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Training Materials<a class=\"headerlink\" href=\"#training-materials\" title=\"Link to this heading\">#</a></h1><p>This is a curated list of related reading materials, free training,\nworkshops, and similar resources, with an emphasis on cloud\ninfrastructure in clinical research settings.</p>", "a[href=\"#authoring\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Authoring<a class=\"headerlink\" href=\"#authoring\" title=\"Link to this heading\">#</a></h2><p>This document is written using\n<a class=\"reference external\" href=\"https://myst-parser.readthedocs.io/\">MyST Markdown</a>, a strict\nsuperset of the\n<a class=\"reference external\" href=\"https://spec.commonmark.org/\">CommonMark syntax specification</a> that\nadds features focused on scientific and technical documentation\nauthoring.  Markdown is specifically designed to be readable across\nmultiple devices in a variety of formats without requiring an online\nInternet connection.  Formatting, collaborative editing, and\npublishing follows the same standards and practices described herein.</p>", "a[href=\"#scope\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Scope<a class=\"headerlink\" href=\"#scope\" title=\"Link to this heading\">#</a></h2><p>This document governs the life cycle of the RDCT Engineering team\u2019s\nproducts or services.  It incorporates material from several sources,\nincluding the following:</p>", "a[href=\"agile/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Project Management<a class=\"headerlink\" href=\"#project-management\" title=\"Link to this heading\">#</a></h1><p>Agile project management methodologies, including\n<a class=\"reference external\" href=\"https://en.wikipedia.org/wiki/Kanban_(development)#\">Kanban</a>,\n<a class=\"reference external\" href=\"https://en.wikipedia.org/wiki/Scrum_(software_development)#\">Scrum</a>, and\n<a class=\"reference external\" href=\"https://en.wikipedia.org/wiki/Scaled_Agile_Framework#\">SAFe</a>, facilitate the incremental\ndelivery of complex products or services with indeterminate (or\nchanging) requirements by shortening and interleaving enterprise\nperformance life cycle phases.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
